import pathlib,json,hashlib,datetime
from bs4 import BeautifulSoup
root=pathlib.Path('outputs/ReBlei/investigations/2026-11-04-official-records');base=root/'continuation-3/employment';sources=json.loads((base/'sources.json').read_text());logs=json.loads((base/'search-log.json').read_text(encoding='utf-8-sig'))
prior=json.loads((root/'continuation-2/inferent/sources.json').read_text())
index=next(x for x in prior if x.get('file','').endswith('part2-archive.html'));reused=dict(index);reused['document_id']='EMP4-REUSED-INDEX';reused['source_class']='official_government_catalog_reused_original';reused['reused_from_document_id']=index['document_id'];reused['locator']='2015,2016,2017 archive headings and their anchor href attributes';sources.append(reused)
request_ids=[]
for p in sorted((base/'raw').glob('*.request.json')):
 a=json.loads(p.read_text());id=p.name.removesuffix('.request.json');request_ids.append(id);sources.append(dict(document_id=id,url=a['url'],file=p.relative_to(root).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),retrieved_at_utc=a['completed_at_utc'],source_class='researcher_http_request_metadata',status='access_failure',http_status=a.get('http_status'),locator='requested_range,http_status,headers,error',limitations='This file is request metadata, not original ZIP bytes or an archive inventory; the HTTP403 response body was not downloaded by bounded range helper.'));logs.append(dict(log_id=id,method='Public HTTP Range GET',url=a['url'],retrieved_at_utc=a['completed_at_utc'],requested_range=a['requested_range'],http_status=a.get('http_status'),outcome='access_failure_not_negative_search',source_id=id))
for s in sources[:2]:logs.append(dict(log_id=s['document_id'],method='Public HTTP GET',url=s['url'],retrieved_at_utc=s['retrieved_at_utc'],http_status=s['http_status'],source_id=s['document_id'],outcome='access_failure_not_negative_search'))
claims=[dict(claim_id='EMP4-C01',statement='The previously preserved original SEC Form ADV Part2 archive catalogue lists ten2017ZIPs, eight2016ZIPs and ten2015ZIPs grouped by periods. These public links were used without guessing member filenames.',status='verified_catalogue_content',source_ids=['EMP4-REUSED-INDEX'],locators=['2015,2016,2017 headings and anchors']),dict(claim_id='EMP4-C02',statement='All ten listed2017ZIPs and five selected2015/2016ZIPs returnedHTTP403 on their first bounded range requests in this pass. No central directory or Ophir member was retrieved from those requests. Untested2015/2016parts remain untested.',status='verified_bounded_access_observation_not_absence',source_ids=request_ids,locators=['requested_range bytes=-65536; http_status403; error']),dict(claim_id='EMP4-C03',statement='No original historical Ophir Part2A/2B brochure or Bleich career biography was obtained in this pass. Earlier employment dates and latest-brochure-ID247246 remain unresolved; a blocked archive request does not establish that a brochure or biography is absent.',status='research_gap_no_employment_upgrade',source_ids=request_ids+['EMP4-CATALOG0','EMP4-CATALOG1'],locators=['Public archive access requests; complete logged scope'])]
(base/'sources.json').write_text(json.dumps(sources,indent=2),encoding='utf-8');(base/'claims.json').write_text(json.dumps(claims,indent=2),encoding='utf-8');(base/'search-log.json').write_text(json.dumps(logs,indent=2),encoding='utf-8')
# Verify hashes and manifest shape without altering any shared source.
ids=[s['document_id'] for s in sources];assert len(ids)==len(set(ids))
for s in sources:assert hashlib.sha256((root/s['file']).read_bytes()).hexdigest()==s['sha256'],s['document_id']
